/* AIVIC_FUNCTION_BUNDLE_START owner=calculateDemandForecastDeviation exports=calculateDemandForecastDeviation */
const __aivicBundle_5_calculateDemandForecastDeviation = (() => {
  function calculateDemandForecastDeviation(
    forecastData: {
      predictedSalesQuantity: number;
      predictedInventoryQuantity: number;
      forecastTimestamp: Date;
    },
    actualData: {
      actualSalesQuantity: number;
      actualInventoryQuantity: number;
      actualTimestamp: Date;
    }
  ): DeviationResult {
    // Validation: 予測値がゼロ以下の場合はエラー
    if (forecastData.predictedSalesQuantity <= 0 || forecastData.predictedInventoryQuantity <= 0) {
      throw new Error('予測値は0より大きい値である必要があります');
    }
  
    // Validation: 実績値が負の場合はエラー
    if (actualData.actualSalesQuantity < 0 || actualData.actualInventoryQuantity < 0) {
      throw new Error('実績値は負の値であってはいけません');
    }
  
    // 絶対乖離値を計算
    const absoluteSalesDeviation = Math.abs(
      actualData.actualSalesQuantity - forecastData.predictedSalesQuantity
    );
    const absoluteInventoryDeviation = Math.abs(
      actualData.actualInventoryQuantity - forecastData.predictedInventoryQuantity
    );
  
    // 乖離率を計算（パーセンテージ）
    const salesDeviationRate =
      (absoluteSalesDeviation / forecastData.predictedSalesQuantity) * 100;
    const inventoryDeviationRate =
      (absoluteInventoryDeviation / forecastData.predictedInventoryQuantity) * 100;
  
    // 平均乖離度を計算
    const averageDeviationRate = (salesDeviationRate + inventoryDeviationRate) / 2;
  
    // 乖離度の分類を決定
    let deviationClassification: 'good' | 'standard' | 'needsImprovement';
    if (averageDeviationRate <= 1) {
      deviationClassification = 'good';
    } else if (averageDeviationRate <= 10) {
      deviationClassification = 'standard';
    } else {
      deviationClassification = 'needsImprovement';
    }
  
    // 乖離トレンドを判定
    const deviationTrend =
      averageDeviationRate > 15
        ? '悪化傾向'
        : averageDeviationRate > 5
          ? '注視中'
          : '良好';
  
    // カテゴリ別の乖離率を構築
    const categoryBreakdown = [
      {
        category: '売上数量',
        deviationRate: salesDeviationRate
      },
      {
        category: '在庫量',
        deviationRate: inventoryDeviationRate
      }
    ];
  
    return {
      salesDeviationRate,
      inventoryDeviationRate,
      averageDeviationRate,
      absoluteSalesDeviation,
      absoluteInventoryDeviation,
      deviationClassification,
      deviationTrend,
      categoryBreakdown
    };
  }
  return { calculateDemandForecastDeviation };
})();
export const calculateDemandForecastDeviation = __aivicBundle_5_calculateDemandForecastDeviation.calculateDemandForecastDeviation;
