/* AIVIC_FUNCTION_BUNDLE_START owner=determineMenuPriorityConditions exports=determineMenuPriorityConditions */
const __aivicBundle_46_determineMenuPriorityConditions = (() => {
  function determineMenuPriorityConditions(input: {
    monthlyBudget: number;
    accumulatedExpense: number;
    nutritionStandards: Record<string, { target: number; actual: number }>;
    budgetExceeded: boolean;
    allNutritionStandardsMet: boolean;
  }): {
    remainingBudget: number;
    budgetStatus: string;
    nutritionStatus: string;
    judgmentStatus: string;
    priorityCondition: string;
    recommendedMenuPriority: string;
  } {
    const remainingBudget = input.monthlyBudget - input.accumulatedExpense;
  
    const budgetStatus = input.budgetExceeded ? "budget_exceeded" : "within_budget";
    const nutritionStatus = input.allNutritionStandardsMet
      ? "all_standards_met"
      : "nutrition_deficiency";
  
    let judgmentStatus: string;
    let priorityCondition: string;
    let recommendedMenuPriority: string;
  
    if (!input.budgetExceeded && input.allNutritionStandardsMet) {
      judgmentStatus = "conditions_satisfied";
      priorityCondition = "balanced";
      recommendedMenuPriority = "standard";
    } else if (input.budgetExceeded && !input.allNutritionStandardsMet) {
      judgmentStatus = "conditions_not_satisfied";
      priorityCondition = "nutrition_first";
      recommendedMenuPriority = "cost_reduction";
    } else if (input.budgetExceeded && input.allNutritionStandardsMet) {
      judgmentStatus = "conditions_partially_satisfied";
      priorityCondition = "cost_optimization";
      recommendedMenuPriority = "budget_priority";
    } else {
      judgmentStatus = "conditions_partially_satisfied";
      priorityCondition = "nutrition_focus";
      recommendedMenuPriority = "nutrition_priority";
    }
  
    return {
      remainingBudget,
      budgetStatus,
      nutritionStatus,
      judgmentStatus,
      priorityCondition,
      recommendedMenuPriority,
    };
  }
  return { determineMenuPriorityConditions };
})();
