const __aivicBundle_47_calculateBudgetOverage = (() => {
  interface CalculateBudgetOverageInput {
    budget: number;
    actual: number;
  }
  
   function calculateBudgetOverage(
    input: CalculateBudgetOverageInput
  ): number {
    const { budget, actual } = input;
  
    if (budget <= 0) {
      throw new Error("予算は0より大きい値である必要があります");
    }
  
    if (actual < 0) {
      throw new Error("実績は0以上である必要があります");
    }
  
    const overageAmount = Math.max(0, actual - budget);
    return overageAmount;
  }
  return { calculateBudgetOverage };
})();
