    const currentTime = inputData.currentTime ? new Date(inputData.currentTime) : new Date();
    const slaThreshold = inputData.slaThresholdSeconds ?? 60;
    
    const elapsedSeconds = (currentTime.getTime() - startTime.getTime()) / 1000;
